import csv

# Read the original file
with open('outputs/t11_city_indicator_matrix.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    rows = list(reader)

# Count missing values
indicator_missing_count = {col: 0 for col in header[3:]}
total_rows = len(rows)

for row in rows:
    for i, col in enumerate(header[3:]):
        if i >= len(row) or row[i] == '':
            indicator_missing_count[col] += 1

print('Verification of missing counts:')
for col in indicator_missing_count:
    print(f'  {col}: {indicator_missing_count[col]} (expected: 0 for DE1001V, DE1002V, DE3001V; 454 for DE3017V)')
